const vw = g.getWidth();
const bgWidth = 384;

const sonic = {
  bpp: 4,
  transparent: 1,
};

const defaultSonic = {
  width: 46,
  height: 62,
  buffer: require("heatshrink").decompress(atob("")),
};

const startingBuffers = [
  {
    width: 60,
    height: 62,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 62,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 42,
    height: 62,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 56,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 62,
    height: 62,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 41,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 53,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 53,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 52,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 53,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
];

const stoppingBuffers = [
  {
    width: 58,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 57,
    height: 60,
    buffer: require("heatshrink").decompress(atob("")),
  },
];

const waitingBuffers = [
  {
    width: 48,
    height: 62,
    offset: 0,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 51,
    height: 62,
    offset: 2,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 51,
    height: 62,
    offset: 2,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 51,
    height: 62,
    offset: 2,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 51,
    height: 62,
    offset: 2,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 51,
    height: 62,
    offset: 2,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 52,
    height: 60,
    offset: 2,
    buffer: require("heatshrink").decompress(atob("")),
  },
  {
    width: 57,
    height: 60,
    offset: 5,
    buffer: require("heatshrink").decompress(atob("")),
  },
];

const bg = {
  width: 384,
  height: 153,
  bpp: 4,
  buffer: require("heatshrink").decompress(atob("")),
};

const topSpeed = 15;
const timeout = 150;
let currentSpeed = 0;
let currentSonic = -1;

let drawTimeout, drawInterval, waitTimeout;
let bgScroll = [0, null];

const fullReset = () => {
  if (drawTimeout) clearTimeout(drawTimeout);
  if (waitTimeout) clearTimeout(waitTimeout);
  if (drawInterval) clearInterval(drawInterval);
  currentSonic = -1;
  currentSpeed = 0;
};

const start = () => {
  fullReset();

  drawInterval = setInterval(() => {
    draw("start");
    bgScroll[0] += currentSpeed;
    if (bgScroll[1]) bgScroll[1] += currentSpeed;
    if (currentSpeed < topSpeed) currentSpeed++;
  }, timeout);
};

const stop = () => {
  if (drawTimeout) clearTimeout(drawTimeout);
  if (drawInterval) clearInterval(drawInterval);

  drawInterval = setInterval(() => {
    if (currentSpeed <= 0) {
      clearInterval(drawInterval);
      draw("reset");
    } else {
      draw("stop");
      bgScroll[0] += currentSpeed;
      if (bgScroll[1]) bgScroll[1] += currentSpeed;
      currentSpeed--;
    }
  }, timeout);
};

const wait = () => {
  currentSonic = -1;
  currentSpeed = 0;
  if (drawTimeout) clearTimeout(drawTimeout);
  if (drawInterval) clearInterval(drawInterval);

  drawInterval = setInterval(() => draw("wait"), timeout);

  waitTimeout = setTimeout(() => {
    clearInterval(drawInterval);
    currentSonic = -1;
    draw("reset");
  }, 7500);
};

const queueDraw = () => {
  if (drawTimeout) clearTimeout(drawTimeout);
  drawTimeout = setTimeout(function () {
    drawTimeout = undefined;
    draw("reset");
  }, 60000 - (Date.now() % 60000));
};

const waitingSequence = [
  // 1. Initial complete idle animation
  0, 1, 1,
  // Foot tap
  2, 3, 2, 3,
  // Finger wag
  4, 5, 4, 5,
  // Impatient beckon and forward arm point (held)
  6, 7, 7, 7, 7,
  // 2. Transition back to hands on hips
  1,
  // 3. Repeating foot taps loop
  2, 3,
];
const waitingLoopStart = waitingSequence.length - 2;

const drawSonic = (action) => {
  let target;

  if (action === "reset" || currentSonic === -1) {
    target = defaultSonic;
  } else if (action === "start") {
    target = startingBuffers[currentSonic];
  } else if (action === "stop") {
    if (currentSonic > 1) currentSonic = 0;
    target = stoppingBuffers[currentSonic];
  } else {
    target = waitingBuffers[waitingSequence[currentSonic]];
  }

  sonic.width = target.width;
  sonic.height = target.height;
  sonic.buffer = target.buffer;
  sonic.offset = target.offset;

  g.drawImage(
    sonic,
    vw / 2 - 30 + (50 - sonic.width) + (sonic.offset || 0),
    86 + (65 - sonic.height)
  );

  if (action === "start") {
    if (currentSonic === startingBuffers.length - 1) {
      currentSonic = 6;
    } else {
      currentSonic++;
    }
  } else if (action === "stop") {
    if (currentSpeed <= 2) {
      currentSonic = -1;
    } else if (currentSpeed <= 14) {
      currentSonic = 1;
    } else {
      currentSonic = 0;
    }
  } else {
    if (currentSonic === waitingSequence.length - 1) {
      currentSonic = waitingLoopStart;
    } else {
      currentSonic++;
    }
  }
};

let lastTimeStr = "";
let lastDateStr = "";
let lastTimeMin = -1;

const drawTime = () => {
  const x = vw / 2;
  const y = 24 + 25;

  const now = Date.now();
  const currentMin = Math.floor(now / 60000);
  if (currentMin !== lastTimeMin) {
    lastTimeMin = currentMin;
    const date = new Date(now);
    lastTimeStr = require("locale").time(date, 1).trim();
    lastDateStr = require("locale").date(date).toUpperCase();
  }

  g.setColor("#000");
  g.setFontAlign(0, 0).setFont("6x8", 5);
  g.drawString(lastTimeStr, x + 3, y + 2);

  g.setFont("6x8", 1.5);
  g.drawString(lastDateStr, x + 1, y + 29);

  g.setColor("#fff");
  g.setFontAlign(0, 0).setFont("6x8", 5);
  g.drawString(lastTimeStr, x, y);

  g.setFont("6x8", 1.5);
  g.drawString(lastDateStr, x, y + 28);
};

const draw = (action) => {
  if (action === "wait") {
    g.setClipRect(44, 86, 116, 153);
    g.drawImage(bg, -bgScroll[0], 24);
    if (bgScroll[1]) g.drawImage(bg, -bgScroll[1], 24);
    drawSonic(action);
    g.setClipRect(0, 0, vw - 1, g.getHeight() - 1);
    return;
  }

  if (bgWidth - bgScroll[0] < 0) {
    bgScroll[0] = bgScroll[1];
    bgScroll[1] = null;
  }

  g.drawImage(bg, -bgScroll[0], 24);

  if (bgWidth - bgScroll[0] < vw) {
    bgScroll[1] = bgScroll[0] - bgWidth;
    g.drawImage(bg, -bgScroll[1], 24);
  }

  drawSonic(action);
  drawTime();
  if (action === "reset") queueDraw();
};

// Settings
const settings = require("Storage").readJSON("sonic3clk-settings") || {
  activeMode: false,
  twistThreshold: 1600,
};
let isSettings = false;

const settingsMenu = {
  "": { title: "Settings" },
  "Active Mode": {
    value: settings.activeMode,
    onchange: (v) => (settings.activeMode = v),
  },
  "Twist Thresh": {
    value: settings.twistThreshold,
    min: 800,
    max: 4000,
    step: 200,
    onchange: (v) => (settings.twistThreshold = v),
  },
  Exit: () => {
    isSettings = false;

    require("Storage").writeJSON("sonic3clk-settings", settings);
    Bangle.setOptions({
      lockTimeout: 10000,
      backlightTimeout: 12000,
      twistThreshold: settings.twistThreshold,
      wakeOnTwist: !settings.activeMode,
    });

    E.showMenu();
    Bangle.setUI("clock");
    draw("reset");
    start();
  },
};

g.setTheme({ bg: "#0099ff", fg: "#fff", dark: true }).clear();

Bangle.on("lock", (locked) => {
  if (!isSettings) {
    if (locked) {
      stop();
    } else {
      start();
    }
  }
});

Bangle.on("twist", () => {
  if (settings.activeMode) {
    fullReset();
    draw("reset");
  } else {
    wait();
  }
});

Bangle.on("tap", (d) => {
  if (d.double && d.dir === "top") {
    fullReset();
    isSettings = true;
    Bangle.setLocked(false);
    E.showMenu(settingsMenu);
  }
});

Bangle.setOptions({
  lockTimeout: 10000,
  backlightTimeout: 12000,
  twistThreshold: settings.twistThreshold,
  wakeOnTwist: !settings.activeMode,
});

Bangle.setUI("clock");

Bangle.loadWidgets();
Bangle.drawWidgets();

draw("reset");

if (Bangle.isLocked()) {
  stop();
} else {
  start();
}
